create extension if not exists pgcrypto;
create table if not exists public.gifts(id bigint generated by default as identity primary key,name text not null,category text not null,description text not null default '',image_url text not null default '',purchase_url text not null default '',desired integer not null default 1 check(desired between 1 and 50),hidden boolean not null default false,sort_order integer not null default 0);
create table if not exists public.gift_units(id bigint generated by default as identity primary key,gift_id bigint not null references public.gifts(id) on delete cascade,status text not null default 'available' check(status in ('available','reserved','received')),reservation_id bigint);
create table if not exists public.reservations(id bigint generated by default as identity primary key,gift_id bigint not null references public.gifts(id) on delete cascade,name text not null,phone text not null default '',message text not null default '',quantity integer not null check(quantity between 1 and 50),created_at timestamptz not null default now());
alter table public.gift_units drop constraint if exists gift_units_reservation_fk;alter table public.gift_units add constraint gift_units_reservation_fk foreign key(reservation_id) references public.reservations(id) on delete set null;
create table if not exists public.messages(id bigint generated by default as identity primary key,name text not null,message text not null,created_at timestamptz not null default now());
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade);
create index if not exists gift_units_lookup_idx on public.gift_units(gift_id,status);
alter table public.gifts enable row level security;alter table public.gift_units enable row level security;alter table public.reservations enable row level security;alter table public.messages enable row level security;alter table public.admins enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.admins where user_id=auth.uid())$$;
create or replace function public.get_gift_catalog() returns table(id bigint,name text,category text,description text,image_url text,purchase_url text,desired integer,sort_order integer,available bigint,reserved bigint,received bigint) language sql stable security definer set search_path=public,pg_temp as $$select g.id,g.name,g.category,g.description,g.image_url,g.purchase_url,g.desired,g.sort_order,count(u.id) filter(where u.status='available'),count(u.id) filter(where u.status='reserved'),count(u.id) filter(where u.status='received') from gifts g left join gift_units u on u.gift_id=g.id where not g.hidden group by g.id order by g.sort_order,g.id$$;
create or replace function public.reserve_gift(p_gift_id bigint,p_quantity integer,p_name text,p_phone text default '',p_message text default '') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare r_id bigint;unit_ids bigint[];begin if char_length(trim(p_name))<1 or p_quantity<1 or p_quantity>20 then return jsonb_build_object('ok',false,'error','Dados inválidos.');end if;select array_agg(id) into unit_ids from(select id from gift_units where gift_id=p_gift_id and status='available' order by id for update skip locked limit p_quantity)s;if coalesce(array_length(unit_ids,1),0)<>p_quantity then return jsonb_build_object('ok',false,'error','Quantidade indisponível.');end if;insert into reservations(gift_id,name,phone,message,quantity) values(p_gift_id,left(trim(p_name),100),left(coalesce(p_phone,''),40),left(coalesce(p_message,''),1000),p_quantity) returning id into r_id;update gift_units set status='reserved',reservation_id=r_id where id=any(unit_ids);return jsonb_build_object('ok',true);end$$;
create or replace function public.submit_message(p_name text,p_message text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if char_length(trim(p_name))<1 or char_length(trim(p_message))<1 then return jsonb_build_object('ok',false);end if;insert into messages(name,message) values(left(trim(p_name),100),left(trim(p_message),2000));return jsonb_build_object('ok',true);end$$;
create or replace function public.admin_get_data() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not is_admin() then raise exception 'not authorized';end if;return jsonb_build_object('gifts',(select coalesce(jsonb_agg(x order by sort_order,id),'[]') from(select g.*,count(u.id) filter(where u.status='available') available,count(u.id) filter(where u.status='reserved') reserved,count(u.id) filter(where u.status='received') received from gifts g left join gift_units u on u.gift_id=g.id group by g.id)x),'reservations',(select coalesce(jsonb_agg(x order by created_at desc),'[]') from(select r.*,g.name gift_name from reservations r join gifts g on g.id=r.gift_id)x),'messages',(select coalesce(jsonb_agg(m order by created_at desc),'[]') from messages m));end$$;
create or replace function public.admin_save_gift(p_gift jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare gid bigint;wanted integer;current_count integer;remove_count integer;begin if not is_admin() then raise exception 'not authorized';end if;wanted=greatest(1,least(50,coalesce((p_gift->>'desired')::integer,1)));gid=nullif(p_gift->>'id','')::bigint;if gid is null then insert into gifts(name,category,description,image_url,purchase_url,desired,hidden,sort_order) values(p_gift->>'name',p_gift->>'category',coalesce(p_gift->>'description',''),coalesce(p_gift->>'image_url',''),coalesce(p_gift->>'purchase_url',''),wanted,coalesce((p_gift->>'hidden')::boolean,false),coalesce((p_gift->>'sort_order')::integer,0)) returning id into gid;current_count=0;else update gifts set name=p_gift->>'name',category=p_gift->>'category',description=coalesce(p_gift->>'description',''),image_url=coalesce(p_gift->>'image_url',''),purchase_url=coalesce(p_gift->>'purchase_url',''),hidden=coalesce((p_gift->>'hidden')::boolean,false),sort_order=coalesce((p_gift->>'sort_order')::integer,0) where id=gid;select count(*) into current_count from gift_units where gift_id=gid;end if;if wanted>current_count then insert into gift_units(gift_id) select gid from generate_series(1,wanted-current_count);elsif wanted<current_count then remove_count=current_count-wanted;delete from gift_units where id in(select id from gift_units where gift_id=gid and status='available' order by id desc limit remove_count);end if;select count(*) into current_count from gift_units where gift_id=gid;update gifts set desired=current_count where id=gid;return jsonb_build_object('ok',true,'id',gid);end$$;
create or replace function public.admin_delete_gift(p_gift_id bigint) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not is_admin() then raise exception 'not authorized';end if;delete from gifts where id=p_gift_id;return jsonb_build_object('ok',true);end$$;
create or replace function public.admin_update_reservation(p_reservation_id bigint,p_action text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not is_admin() then raise exception 'not authorized';end if;if p_action='received' then update gift_units set status='received' where reservation_id=p_reservation_id;elsif p_action='release' then update gift_units set status='available',reservation_id=null where reservation_id=p_reservation_id;delete from reservations where id=p_reservation_id;else return jsonb_build_object('ok',false,'error','Ação inválida.');end if;return jsonb_build_object('ok',true);end$$;
revoke all on public.gifts,public.gift_units,public.reservations,public.messages,public.admins from anon,authenticated;grant execute on function public.get_gift_catalog() to anon,authenticated;grant execute on function public.reserve_gift(bigint,integer,text,text,text) to anon,authenticated;grant execute on function public.submit_message(text,text) to anon,authenticated;grant execute on function public.admin_get_data(),public.admin_save_gift(jsonb),public.admin_delete_gift(bigint),public.admin_update_reservation(bigint,text) to authenticated;
insert into storage.buckets(id,name,public) values('gift-images','gift-images',true) on conflict(id) do update set public=true;
drop policy if exists "admins upload gift images" on storage.objects;create policy "admins upload gift images" on storage.objects for insert to authenticated with check(bucket_id='gift-images' and public.is_admin());
